const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const T = readInt();

    const t = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        t[i] = readInt();
    }

    const p = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        p[i] = readInt();
    }

    const C = readInt();
    const u = new Int32Array(C);
    for (let i = 0; i < C; i++) {
        u[i] = readInt();
    }

    // Agrupar preços por tipo
    // Usaremos contagem para montar arrays compactos
    const count = new Int32Array(T + 1);
    for (let i = 0; i < N; i++) {
        count[t[i]]++;
    }

    const L = new Array(T + 1);
    for (let i = 1; i <= T; i++) {
        if (count[i] > 0) {
            L[i] = new Int32Array(count[i]);
            count[i] = 0; // reutilizar como ponteiro de inserção
        } else {
            L[i] = null;
        }
    }

    for (let i = 0; i < N; i++) {
        const type = t[i];
        L[type][count[type]++] = p[i];
    }

    for (let i = 1; i <= T; i++) {
        if (L[i] !== null) {
            L[i].sort();
        }
    }

    const head = new Int32Array(T + 1);

    // Min-Heap implementado com arrays paralelos para alta performance
    // Heap armazena: (price, type, idx)
    // Capacidade máxima é N + 1
    const heapPrice = new Int32Array(N + 2);
    const heapType = new Int32Array(N + 2);
    const heapIdx = new Int32Array(N + 2);
    let heapSize = 0;

    function push(price, type, idx) {
        heapSize++;
        let i = heapSize;
        while (i > 1) {
            const pIdx = i >> 1;
            const pPrice = heapPrice[pIdx];
            const pType = heapType[pIdx];
            if (price < pPrice || (price === pPrice && type < pType)) {
                heapPrice[i] = pPrice;
                heapType[i] = pType;
                heapIdx[i] = heapIdx[pIdx];
                i = pIdx;
            } else {
                break;
            }
        }
        heapPrice[i] = price;
        heapType[i] = type;
        heapIdx[i] = idx;
    }

    function pop() {
        const topPrice = heapPrice[1];
        const topType = heapType[1];
        const topIdx = heapIdx[1];

        const lastPrice = heapPrice[heapSize];
        const lastType = heapType[heapSize];
        const lastIdx = heapIdx[heapSize];
        heapSize--;

        if (heapSize > 0) {
            let i = 1;
            while ((i << 1) <= heapSize) {
                let child = i << 1;
                if (child + 1 <= heapSize) {
                    const c1Price = heapPrice[child];
                    const c1Type = heapType[child];
                    const c2Price = heapPrice[child + 1];
                    const c2Type = heapType[child + 1];
                    if (c2Price < c1Price || (c2Price === c1Price && c2Type < c1Type)) {
                        child++;
                    }
                }
                const cPrice = heapPrice[child];
                const cType = heapType[child];
                if (cPrice < lastPrice || (cPrice === lastPrice && cType < lastType)) {
                    heapPrice[i] = cPrice;
                    heapType[i] = cType;
                    heapIdx[i] = heapIdx[child];
                    i = child;
                } else {
                    break;
                }
            }
            heapPrice[i] = lastPrice;
            heapType[i] = lastType;
            heapIdx[i] = lastIdx;
        }

        return { price: topPrice, type: topType, idx: topIdx };
    }

    // Inicializar o heap com o primeiro elemento de cada tipo existente
    for (let i = 1; i <= T; i++) {
        if (L[i] !== null && L[i].length > 0) {
            push(L[i][0], i, 0);
        }
    }

    let totalRevenue = 0n;

    for (let j = 0; j < C; j++) {
        const uj = u[j];
        if (uj === 0) {
            // Cliente indeciso
            while (heapSize > 0) {
                const cur = pop();
                if (cur.idx !== head[cur.type]) {
                    // Elemento desatualizado
                    continue;
                }
                // Elemento válido encontrado
                const type = cur.type;
                totalRevenue += BigInt(cur.price);
                head[type]++;
                if (head[type] < L[type].length) {
                    push(L[type][head[type]], type, head[type]);
                }
                break;
            }
        } else {
            // Cliente decidido
            const type = uj;
            if (L[type] !== null && head[type] < L[type].length) {
                const price = L[type][head[type]];
                totalRevenue += BigInt(price);
                head[type]++;
                if (head[type] < L[type].length) {
                    push(L[type][head[type]], type, head[type]);
                }
            }
        }
    }

    console.log(totalRevenue.toString());
}

